#include <iostream>
#include <map>
#include <vector>
using namespace std;

const int MOD = 1000000007;

struct BigInt {
    int v;

    BigInt(long long val = 0) {
        if (val < 0) val %= MOD, val += MOD;
        if (val >= MOD) val %= MOD;
        v = val;
    }

    static int modInverse(int a, int m = MOD) {
        int g = m, r = a, x = 0, y = 1;
        while (r != 0) {
            int q = g / r;
            g %= r; swap(g, r);
            x -= q * y; swap(x, y);
        }
        return x < 0 ? x + m : x;
    }

    explicit operator int() const { return v; }

    BigInt& operator+=(const BigInt &other) {
        v += other.v;
        if (v >= MOD) v -= MOD;
        return *this;
    }

    BigInt& operator-=(const BigInt &other) {
        v -= other.v;
        if (v < 0) v += MOD;
        return *this;
    }

    static unsigned fast_mod(uint64_t x, unsigned m = MOD) {
    #if !defined(_WIN32) || defined(_WIN64)
        return x % m;
    #endif
        unsigned high = x >> 32, low = (unsigned) x;
        unsigned q, r;
        asm("divl %4\n"
            : "=a" (q), "=d" (r)
            : "d" (high), "a" (low), "r" (m));
        return r;
    }

    BigInt& operator*=(const BigInt &other) {
        v = fast_mod((uint64_t) v * other.v);
        return *this;
    }

    BigInt& operator/=(const BigInt &other) {
        return *this *= BigInt(modInverse(other.v));
    }

    friend BigInt operator+(const BigInt &a, const BigInt &b) { return BigInt(a) += b; }
    friend BigInt operator-(const BigInt &a, const BigInt &b) { return BigInt(a) -= b; }
    friend BigInt operator*(const BigInt &a, const BigInt &b) { return BigInt(a) *= b; }
    friend BigInt operator/(const BigInt &a, const BigInt &b) { return BigInt(a) /= b; }

    BigInt& operator++() {
        v = v == MOD - 1 ? 0 : v + 1;
        return *this;
    }

    BigInt& operator--() {
        v = v == 0 ? MOD - 1 : v - 1;
        return *this;
    }

    BigInt operator++(int) { BigInt before = *this; ++*this; return before; }
    BigInt operator--(int) { BigInt before = *this; --*this; return before; }

    BigInt operator-() const {
        return v == 0 ? 0 : MOD - v;
    }

    bool operator==(const BigInt &other) const { return v == other.v; }
    bool operator!=(const BigInt &other) const { return v != other.v; }

    BigInt inv() const {
        return BigInt(modInverse(v));
    }

    BigInt pow(long long p) const {
        assert(p >= 0);
        BigInt base = *this, result = 1;
        while (p > 0) {
            if (p & 1)
                result *= base;
            base *= base;
            p >>= 1;
        }
        return result;
    }
};

