import java.util.*;
import java.io.*;

public class Main {
    static final int MOD = 1000000007;

    static class BigInt {
        int v;

        BigInt(long val) {
            if (val < 0) {
                val %= MOD;
                val += MOD;
            }
            if (val >= MOD) {
                val %= MOD;
            }
            this.v = (int) val;
        }

        static int modInverse(int a, int m) {
            int g = m, r = a, x = 0, y = 1;
            while (r != 0) {
                int q = g / r;
                int temp = g % r;
                g = r;
                r = temp;
                int x1 = x - q * y;
                x = y;
                y = x1;
            }
            return x < 0 ? x + m : x;
        }

        public static BigInt operatorAdd(BigInt a, BigInt b) {
            return new BigInt((a.v + b.v) % MOD);
        }

        public static BigInt operatorSubtract(BigInt a, BigInt b) {
            int res = a.v - b.v;
            if (res < 0) res += MOD;
            return new BigInt(res);
        }

        public static BigInt operatorMultiply(BigInt a, BigInt b) {
            long res = (long) a.v * b.v;
            return new BigInt(res % MOD);
        }

        public static BigInt operatorDivide(BigInt a, BigInt b) {
            return a.operatorMultiply(new BigInt(modInverse(b.v, MOD)));
        }

        public BigInt inv() {
            return new BigInt(modInverse(this.v, MOD));
        }

        public BigInt pow(long p) {
            assert p >= 0;
            BigInt base = this;
            BigInt result = new BigInt(1);
            while (p > 0) {
                if ((p & 1) != 0) {
                    result = operatorMultiply(result, base);
                }
                base = operatorMultiply(base, base);
                p >>= 1;
            }
            return result;
        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) return true;
            if (!(obj instanceof BigInt)) return false;
            BigInt other = (BigInt) obj;
            return this.v == other.v;
        }

        @Override
        public int hashCode() {
            return Integer.hashCode(v);
        }
    }

    static int N;
    static BigInt[][] prob;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        N = Integer.parseInt(br.readLine());
        prob = new BigInt[N][N];

        for (int i = 0; i < N; i++) {
            String[] parts = br.readLine().split("\\s+");
            for (int j = 0; j < N; j++) {
                int p = Integer.parseInt(parts[j]);
                prob[i][j] = new BigInt(p).operatorDivide(new BigInt(100));
            }
        }

        Map<List<Boolean>, BigInt> stateMap = new HashMap<>();
        List<Boolean> initialMask = new ArrayList<>(Collections.nCopies(1 << N, false));
        initialMask.set(0, true);
        stateMap.put(initialMask, new BigInt(1));

        for (int leftIdx = 0; leftIdx < N; leftIdx++) {
            Map<List<Boolean>, BigInt> newStateMap = new HashMap<>();
            for (int maskCurr = 0; maskCurr < (1 << N); maskCurr++) {
                BigInt product = new BigInt(1);
                for (int rightIdx = 0; rightIdx < N; rightIdx++) {
                    boolean bitSet = ((maskCurr >> rightIdx) & 1) != 0;
                    if (bitSet) {
                        product = BigInt.operatorMultiply(product, prob[leftIdx][rightIdx]);
                    } else {
                        product = BigInt.operatorMultiply(product, BigInt.operatorSubtract(new BigInt(1), prob[leftIdx][rightIdx]));
                    }
                }
                for (Map.Entry<List<Boolean>, BigInt> entry : stateMap.entrySet()) {
                    List<Boolean> possibleMask = entry.getKey();
                    BigInt probValue = entry.getValue();
                    List<Boolean> tempMask = new ArrayList<>(Collections.nCopies(1 << N, false));
                    for (int m = 0; m < (1 << N); m++) {
                        if (possibleMask.get(m)) {
                            for (int i = 0; i < N; i++) {
                                boolean maskBit = ((maskCurr >> i) & 1) != 0;
                                boolean mBit = ((m >> i) & 1) != 0;
                                if (maskBit && !mBit) {
                                    tempMask.set(m | (1 << i), true);
                                }
                            }
                        }
                    }
                    BigInt existing = newStateMap.getOrDefault(tempMask, new BigInt(0));
                    newStateMap.put(tempMask, BigInt.operatorAdd(existing, BigInt.operatorMultiply(probValue, product)));
                }
            }
            stateMap = newStateMap;
        }

        BigInt total = new BigInt(0);
        for (Map.Entry<List<Boolean>, BigInt> p : stateMap.entrySet()) {
            List<Boolean> mask = p.getKey();
            if (mask.get((1 << N) - 1)) {
                total = BigInt.operatorAdd(total, p.getValue());
            }
        }

        System.out.println(total.v);
    }
}
